import React from 'react';
import { Document, Page, Text, View, StyleSheet, PDFDownloadLink } from '@react-pdf/renderer';

// Estilos do documento PDF
const styles = StyleSheet.create({
  page: {
    flexDirection: 'column',
    backgroundColor: '#E4E4E4',
    padding: 30,
  },
  section: {
    margin: 10,
    padding: 10,
    flexGrow: 1,
  },
  header: {
    fontSize: 20,
    marginBottom: 20,
  },
  text: {
    fontSize: 14,
  },
});

// Componente que renderiza o conteúdo do PDF
const MyDocument = () => (
  <Document>
    <Page size="A4" style={styles.page}>
      <View style={styles.section}>
        <Text style={styles.header}>Relatório de Exemplo</Text>
        <Text style={styles.text}>Este é um exemplo simples de criação de PDF com React!</Text>
      </View>
      <View style={styles.section}>
        <Text style={styles.text}>Você pode adicionar mais informações aqui conforme necessário.</Text>
      </View>
    </Page>
  </Document>
);

// Componente para download
const DownloadPDF = () => (
  <div>
    <PDFDownloadLink document={<MyDocument />} fileName="meu-relatorio.pdf">
      {({ loading }) => (loading ? 'Carregando documento...' : 'Baixar PDF')}
    </PDFDownloadLink>
  </div>
);

export default DownloadPDF;
